package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.port.MovementGateway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.Types;

/**
 * Adapter of the MovementGateway port. It calls the external program PAGOMOV
 * (exposed as the procedure pagomov) with MOV_ORDEN and returns MOV_NUMERO.
 * The return status of PAGOMOV is not mapped, as in the legacy.
 */
@Repository
public class JdbcMovementGateway implements MovementGateway {

    private final JdbcTemplate jdbcTemplate;

    public JdbcMovementGateway(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public long registerMovement(Integer orderNumber) {
        Long result = jdbcTemplate.execute(
                (java.sql.Connection con) -> {
                    java.sql.CallableStatement cs = con.prepareCall("{call pagomov(?, ?)}");
                    if (orderNumber == null) {
                        cs.setNull(1, Types.INTEGER);
                    } else {
                        cs.setInt(1, orderNumber);
                    }
                    cs.registerOutParameter(2, Types.BIGINT);
                    return cs;
                },
                (java.sql.CallableStatement cs) -> {
                    cs.execute();
                    return cs.getLong(2);
                });
        return result == null ? 0L : result;
    }
}
